"""Validation rules migrated from Meridian CRM 4.2 order_rules.vrl."""

from decimal import Decimal
from typing import Any


def _field(record: dict, column: str) -> Any:
    """Return a field value, treating a missing key as the empty string."""
    return record.get(column, "")


def _number(value: Any) -> Decimal:
    """Apply the legacy numeric coercion required by the migrated rules."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Perform a first-live-row legacy LOOKUP."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")

    return ""


def _failure(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Run applicable migrated rules in legacy rule-file order."""
    errors: list[dict] = []
    old_record = {} if event == "INSERT" or old is None else old

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_field(record, "DISC_PCT"))
            if not (discount >= Decimal(0) and discount <= Decimal(100)):
                errors.append(
                    _failure("E5001", "Discount out of range")
                )

        # ORD-002
        if event == "UPDATE":
            passes = not (
                _number(_field(record, "DISC_PCT")) > Decimal(20)
                and _lookup(
                    tables,
                    "USR_MASTER",
                    "USR_ID",
                    _field(record, "OWNER_UID"),
                    "ROLE_ID",
                )
                != "MGR"
                and _lookup(
                    tables,
                    "USR_MASTER",
                    "USR_ID",
                    _field(record, "OWNER_UID"),
                    "ROLE_ID",
                )
                != "ADMIN"
            )
            if not passes:
                errors.append(
                    _failure(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            passes = not (
                _field(old_record, "STAT_CD") == "I"
                and _field(record, "STAT_CD") != "I"
                and _field(record, "STAT_CD") != "X"
            )
            if not passes:
                errors.append(
                    _failure(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            if not (_number(_field(record, "QTY")) > Decimal(0)):
                errors.append(
                    _failure("E5004", "Quantity must be positive")
                )

        # ORD-005
        if event == "INSERT":
            if (
                _lookup(
                    tables,
                    "PROD_MASTER",
                    "PROD_ID",
                    _field(record, "PROD_ID"),
                    "ACTIVE_FLG",
                )
                != "Y"
            ):
                errors.append(
                    _failure("E5005", "Product not active")
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected failure has BLOCK severity."""
    return any(error.get("severity") == "BLOCK" for error in errors)
